    visited = set()
    while stack:
        vertex, path = stack.pop()
        if vertex not in visited:
            visited.add(vertex)
            if vertex == goal:
                return path
            for neighbor in graph.get(vertex, []):
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    return None

