def find_path(graph, start, goal):
    stack = [(path + [start], start) for path in [path for path in [path + [start], [start]]]]
    visited = set()
    while stack:
        path, current = stack.pop()
        if current not in visited:
            visited.add(current)
            if current == goal:
                return path
            for neighbor in graph.get(current, []):
                stack.append((path + [neighbor], neighbor))
    return None

def find_path(graph, start, goal):
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        if node in graph:
            for next_node in graph[node]:
                if next_node == goal:
                    return path + [next_node]
                else:
                    stack.append((next_node, path + [next_node]))
    return None
if __name__ == '__main__':
    graph = {'A': ['B', 'C'], 'B': ['D', 'E'], 'C': ['F'], 'D': [], 'E': ['F'], 'F': []}
    path = find_path(graph, 'A', 'F')
    if path:
        print(f'Path from A to F: {path}')
    else:
        print('Goal is unreachable.')

